def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_def = sum(1 for a in opp if a == 'D')
    my_def = sum(1 for a in me if a == 'D')

    last_opp = opp[-1]

    # Endgame: exploit confirmed cooperators, stay safe vs others.
    remaining = 100 - n
    if remaining <= 2:
        if opp_def == 0:
            return 'D'
        if last_opp == 'D' or opp_def * 3 >= n:
            return 'D'
        if remaining == 1 and opp_def * 4 <= n:
            return 'D'
        return 'C'

    # Early: build cooperation, retaliate only on clear defection.
    if n < 4:
        if n == 1:
            return 'C'
        if opp_def >= 2:
            return 'D'
        return 'C'

    coop_rate = (n - opp_def) / n

    # Very exploitative opponent: defect hard, rare probe.
    if opp_def * 5 >= n * 3:
        if n % 13 == 0:
            return 'C'
        return 'D'

    # Opponent almost never cooperates: defect, rare test.
    if opp_def * 10 >= n * 9:
        if n % 17 == 0:
            return 'C'
        return 'D'

    # Detect alternating pattern (D on odd/even slots) to break echo:
    # If last two are (op=C, me=D, op=D) style, try cooperating to reset.
    if n >= 4:
        # checks recent window for alternating opponent pattern
        alt = True
        for i in range(max(0, n - 6), n - 1):
            if opp[i] == opp[i + 1]:
                alt = False
                break
        if alt and n >= 6 and opp_def * 2 <= n:
            return 'C'

    # Opponent cooperated last: reciprocate, but occasionally test trusted cooperators.
    if last_opp == 'C':
        # Long trust established: mild endgame foreshadowing only, otherwise cooperate.
        if coop_rate >= 0.85 and n >= 40 and remaining > 12:
            if n % 19 == 0:
                return 'D'
        return 'C'

    # Opponent defected last.
    # Single defection in otherwise cooperative play: forgive quickly.
    if opp_def * 4 <= n and n >= 5:
        # Recent defections count
        recent = opp[-5:]
        rd = sum(1 for x in recent if x == 'D')
        if rd == 1:
            # Forgive immediately to restore mutual cooperation.
            return 'C'
        if rd == 2 and rng.random() < 0.5:
            return 'C'
        # Small punishment
        return 'D'

    # Moderately cooperative: tit-for-tat with forgiveness.
    if coop_rate >= 0.6:
        if n >= 6:
            recent = opp[-4:]
            rd = sum(1 for x in recent if x == 'D')
            if rd <= 1:
                return 'C'
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # Mixed/low cooperation: retaliate but periodically offer a cooperative reset.
    if rng.random() < 0.2:
        return 'C'
    if n % 7 == 0:
        return 'C'
    return 'D'
